insert into public.remedies (id, category, tier, title, description, specific_actions, expected_impact, target_metric) values
  ('rem-Price-t1', 'Price', 1, 'Introduce a value meal and reprice against 3 peers', 'Close the price-to-value gap: reprice flagged items within 10% of the three closest peers and add a combo.', array['Benchmark the 3 nearest peers on the same catalog item', 'Reprice flagged items to within 10% of peer average', 'Launch a lunch value combo']::text[], 'Narrow the peer price gap; +0.6★ on value perception', 'peerGap'),
  ('rem-Price-t2', 'Price', 2, 'Re-engineer the dish so value matches price', 'Add a plated side and upgrade presentation so the perceived value matches the price point.', array['Add a complimentary side to flagged mains', 'Upgrade plating and portion visibility', 'Re-photograph the menu']::text[], 'Lift value sentiment ~0.5', 'sentiment'),
  ('rem-Quality-t1', 'Quality', 1, 'Fire-to-order with a heat-lamp pass-check', 'Hold cooked items no longer than 6 minutes and add a temperature pass-check before serving.', array['Set a 6-minute hold limit on cooked items', 'Add a heat-lamp pass-check station', 'Log temperature at the pass']::text[], 'Cut Quality complaints ~60%', 'categoryComplaints'),
  ('rem-Quality-t2', 'Quality', 2, 'Upgrade the flagged ingredient and retrain the line', 'Switch the lowest-rated ingredient to a higher-grade supplier and run line-cook retraining to spec.', array['Swap the flagged supplier ingredient', 'Run a line-cook retraining on the recipe spec', 'Add a weekly plate audit']::text[], '+0.8★ on the item', 'avgRating'),
  ('rem-Quantity-t1', 'Quantity', 1, 'Increase portion weight 20% on flagged items', 'Re-spec plating and prep sheets so flagged items carry a visibly larger portion.', array['Increase portion weight 20% on flagged items', 'Update prep sheets and plating guides', 'Spot-check portions at the pass']::text[], 'Cut Quantity complaints ~70%', 'categoryComplaints'),
  ('rem-Quantity-t2', 'Quantity', 2, 'Add a complimentary side to flagged mains', 'Bundle a bread or salad side so the plate reads as generous value.', array['Add a bread/salad side to flagged mains', 'Update the menu copy to signal the side']::text[], 'Lift value sentiment ~0.5', 'sentiment'),
  ('rem-Taste-t1', 'Taste', 1, 'Recalibrate seasoning to a standardized spec', 'Standardize seasoning and run a weekly taste panel on the flagged items.', array['Publish a seasoning spec sheet', 'Run a weekly 5-item taste panel', 'Retrain on the spec']::text[], 'Cut Taste complaints ~50%', 'categoryComplaints'),
  ('rem-Taste-t2', 'Taste', 2, 'Revise the recipe with a consulting chef', 'Rework the dish and relaunch it as new and improved.', array['Engage a consulting chef', 'Rework and re-test the recipe', 'Relaunch with new menu copy']::text[], '+0.7★ on the item', 'avgRating'),
  ('rem-Service-t1', 'Service', 1, 'Assign a floor lead with a 5-minute table-touch cadence', 'Introduce a greet + check-back SLA so tables are never ignored.', array['Assign a shift floor lead', 'Set a 5-minute greet SLA', 'Add a 12-minute food-runner check-back']::text[], 'Cut Service complaints ~60%', 'categoryComplaints'),
  ('rem-Service-t2', 'Service', 2, 'Move to section-based serving with handheld ordering', 'Reduce ticket time and errors with section assignment and tableside tablets.', array['Assign servers to fixed sections', 'Add handheld ordering tablets', 'Track ticket times per section']::text[], '+0.7★ overall', 'avgRating'),
  ('rem-WaitingTime-t1', 'WaitingTime', 1, 'Reduce prep-to-table time below 15 minutes', 'Streamline the kitchen so orders reach the table in under 15 minutes.', array['Map the prep-to-table workflow', 'Pre-stage high-volume items at peak', 'Set a 15-minute ticket target with a timer at the pass']::text[], 'Cut WaitingTime complaints ~80%; +2★ at peak', 'categoryComplaints'),
  ('rem-WaitingTime-t2', 'WaitingTime', 2, 'Add 2 staff during 12–2 and 7–9 peak windows', 'Staff the peak windows to the demand curve.', array['Add 2 staff during 12–2 and 7–9', 'Add an expediter at the pass', 'Pre-batch prep before peak']::text[], '+0.8★ at peak', 'avgRating'),
  ('rem-Availability-t1', 'Availability', 1, 'Raise par levels on top-3 items 30% and adopt an 86-board', 'Prevent stock-outs on the best sellers with higher par levels and an 86-board process.', array['Raise par levels 30% on the top-3 items', 'Adopt a live 86-board at the pass', 'Do a mid-service stock check']::text[], 'Cut Availability complaints ~75%', 'categoryComplaints'),
  ('rem-Availability-t2', 'Availability', 2, 'Add a backup supplier and a daily prep forecast', 'De-risk supply with a second supplier and forecast prep to reservations.', array['Onboard a backup supplier', 'Forecast daily prep to reservations', 'Set reorder triggers']::text[], 'Fewer stock-outs; +0.6★', 'avgRating'),
  ('rem-Staff-t1', 'Staff', 1, 'Run a hospitality refresher with 30-minute floor checks', 'Reset staff standards with a short refresher and shift-lead floor checks.', array['Run a 2-hour hospitality refresher', 'Add a shift-lead floor check every 30 minutes', 'Post the service standards']::text[], 'Lift Staff sentiment ~0.5', 'sentiment'),
  ('rem-Staff-t2', 'Staff', 2, 'Revise hiring scorecard and add a service bonus', 'Improve the team over time with a better scorecard and an incentive.', array['Revise the hiring scorecard', 'Add a tipped-out service-quality bonus', 'Introduce peer feedback']::text[], '+0.6★ overall', 'avgRating'),
  ('rem-Cleanliness-t1', 'Cleanliness', 1, 'Adopt an hourly sanitation checklist with sign-off', 'Keep restrooms and tables clean with an hourly checklist.', array['Post an hourly restroom + table checklist', 'Require sign-off each hour', 'Spot-audit at peak']::text[], 'Cut Cleanliness complaints ~70%', 'categoryComplaints'),
  ('rem-Cleanliness-t2', 'Cleanliness', 2, 'Nightly deep-clean and a monthly hygiene audit', 'Escalate to a contracted deep-clean and third-party audit.', array['Schedule a nightly deep-clean contractor', 'Book a monthly third-party hygiene audit']::text[], 'Lift Cleanliness sentiment ~0.5', 'sentiment'),
  ('rem-Menu-t1', 'Menu', 1, 'Add photos, allergen and calorie tags, flag top sellers', 'Make the menu clearer and easier to order from.', array['Add dish photos', 'Add allergen and calorie tags', 'Flag the top-3 sellers']::text[], 'Lift Menu sentiment ~0.4', 'sentiment'),
  ('rem-Menu-t2', 'Menu', 2, 'Redesign the menu and cut the 5 worst-rated items', 'Reorganize categories and remove underperformers.', array['Reorganize menu categories', 'Remove the 5 worst-rated items', 'Re-test the new layout']::text[], '+0.5★ overall', 'avgRating'),
  ('rem-Ambience-t1', 'Ambience', 1, 'Fix lighting and noise in the loud zone', 'Install dimmers and acoustic panels where guests complain.', array['Install dimmers', 'Add acoustic panels in the loud zone', 'Lower background music at peak']::text[], 'Lift Ambience sentiment ~0.4', 'sentiment'),
  ('rem-Ambience-t2', 'Ambience', 2, 'Refresh décor and seating layout', 'Update the flagged section for comfort and flow.', array['Refresh décor in the flagged section', 'Rework the seating layout']::text[], '+0.5★ overall', 'avgRating'),
  ('rem-Delivery-t1', 'Delivery', 1, 'Add insulated bags and a seal-check; cap the radius', 'Protect food quality in transit and limit long drives.', array['Add insulated delivery bags', 'Add a seal-check step', 'Cap the delivery radius to a 20-minute drive']::text[], 'Cut Delivery complaints ~60%', 'categoryComplaints'),
  ('rem-Delivery-t2', 'Delivery', 2, 'Switch to a better-rated delivery partner', 'Move to a partner with live tracking.', array['Evaluate delivery partners', 'Switch to the best-rated partner', 'Enable live order tracking']::text[], '+0.6★ on delivery', 'avgRating'),
  ('rem-Packaging-t1', 'Packaging', 1, 'Switch to leak-proof, vented containers for hot items', 'Stop leaks and sogginess in transit.', array['Switch to leak-proof vented containers', 'Separate wet and dry items', 'Add a napkin/utensil pack']::text[], 'Cut Packaging complaints ~65%', 'categoryComplaints'),
  ('rem-Packaging-t2', 'Packaging', 2, 'Redesign packaging with compartment trays and seals', 'Upgrade to compartment trays with tamper-evident seals.', array['Adopt compartment trays', 'Add tamper-evident seals']::text[], 'Lift Packaging sentiment ~0.4', 'sentiment')
