insert into public.reviews (id, restaurant_id, restaurant_menu_item_id, catalog_item_id, location_id, rating, comment, price, date, food_category, phase, scenario_id, categories, sentiment) values
  ('rev-0001', 'rst-01', 'rmi-01-01', 'cat-01', 'loc-01', 2, 'Tasty but $16 is steep for the size.', 16, '2026-01-06', 'Pizza', 'baseline', 'scn-01', array['Price', 'Quantity']::problem_category[], 'Negative'),
  ('rev-0002', 'rst-01', 'rmi-01-01', 'cat-01', 'loc-01', 2, 'Good flavor, portion small for the price.', 16, '2026-01-09', 'Pizza', 'baseline', 'scn-01', array['Quantity', 'Price']::problem_category[], 'Negative'),
  ('rev-0003', 'rst-01', 'rmi-01-01', 'cat-01', 'loc-01', 1, 'Overpriced and I left hungry.', 16, '2026-01-14', 'Pizza', 'baseline', 'scn-01', array['Price', 'Quantity']::problem_category[], 'Negative'),
  ('rev-0004', 'rst-01', 'rmi-01-05', 'cat-05', 'loc-01', 2, '$17 carbonara in a tiny bowl.', 17, '2026-01-19', 'Pasta', 'baseline', 'scn-01', array['Price', 'Quantity']::problem_category[], 'Negative'),
  ('rev-0005', 'rst-01', 'rmi-01-05', 'cat-05', 'loc-01', 2, 'Rich but not worth the price.', 17, '2026-01-23', 'Pasta', 'baseline', 'scn-01', array['Price']::problem_category[], 'Negative'),
  ('rev-0006', 'rst-01', 'rmi-01-02', 'cat-02', 'loc-01', 3, 'Fine, unremarkable salad.', 12, '2026-01-27', 'Salad', 'baseline', 'scn-01', array[]::problem_category[], 'Neutral'),
