  ('rev-0008', 'rst-01', 'rmi-01-08', 'cat-08', 'loc-01', 5, 'Best dessert in town, great value.', 9, '2026-02-07', 'Dessert', 'baseline', 'scn-01', array[]::problem_category[], 'Positive'),
  ('rev-0009', 'rst-01', 'rmi-01-01', 'cat-01', 'loc-01', 2, 'Great taste, felt overpriced.', 16, '2026-02-12', 'Pizza', 'baseline', 'scn-01', array['Price']::problem_category[], 'Negative'),
  ('rev-0010', 'rst-01', 'rmi-01-02', 'cat-02', 'loc-01', 4, 'Fresh salad, generous size.', 12, '2026-02-18', 'Salad', 'baseline', 'scn-01', array[]::problem_category[], 'Positive'),
  ('rev-0011', 'rst-02', 'rmi-02-06', 'cat-06', 'loc-02', 2, 'Rice was mushy, not fresh.', 15, '2026-01-05', 'Sushi', 'baseline', 'scn-02', array['Quality']::problem_category[], 'Negative'),
  ('rev-0012', 'rst-02', 'rmi-02-06', 'cat-06', 'loc-02', 2, 'Waited 35 minutes for one roll.', 15, '2026-01-10', 'Sushi', 'baseline', 'scn-02', array['WaitingTime']::problem_category[], 'Negative'),
