  ('rev-0020', 'rst-02', 'rmi-02-02', 'cat-02', 'loc-02', 4, 'Good portion, fresh.', 11, '2026-02-25', 'Salad', 'baseline', 'scn-02', array[]::problem_category[], 'Positive'),
  ('rev-0021', 'rst-03', 'rmi-03-04', 'cat-04', 'loc-03', 2, 'Server ignored us for ages.', 15, '2026-01-07', 'Curry', 'baseline', 'scn-03', array['Service']::problem_category[], 'Negative'),
